"""Tests for the WireGuard config parser."""
import pytest

from mobile.shared.config_parser import (
    parse_config,
    validate_config,
    WireGuardConfig,
    InterfaceSection,
    PeerSection,
    is_valid_wg_key,
    mask_private_key,
)


SAMPLE_CONFIG = """# OTT VPN — WireGuard client configuration
# Auto-generated by OTT VPN backend.

[Interface]
PrivateKey = yNYuF+gB0xOQ5j6e7w8x9y0z1A2B3C4D5E6F7G8H9I=
Address = 10.66.0.5/24, fd86::5/64
PresharedKey = dGVzdFBzaA==
DNS = 10.66.0.1
MTU = 1280
PersistentKeepalive = 25

[Peer]
PublicKey = dGVzdFB1Ymxj
PresharedKey = dGVzdFBzaA==
Endpoint = mumbai.vpn.example:51820
AllowedIPs = 0.0.0.0/0, ::/0
PersistentKeepalive = 25
"""


class TestConfigParser:
    def test_parse_interface_section(self):
        config = parse_config(SAMPLE_CONFIG)
        assert config.interface.private_key == "yNYuF+gB0xOQ5j6e7w8x9y0z1A2B3C4D5E6F7G8H9I="
        assert "10.66.0.5/24" in config.interface.addresses
        assert "fd86::5/64" in config.interface.addresses
        assert config.interface.dns == ["10.66.0.1"]
        assert config.interface.mtu == 1280
        assert config.interface.persistent_keepalive == 25

    def test_parse_peer_section(self):
        config = parse_config(SAMPLE_CONFIG)
        assert config.peer.public_key == "dGVzdFB1Ymxj"
        assert config.peer.endpoint == "mumbai.vpn.example:51820"
        assert "0.0.0.0/0" in config.peer.allowed_ips
        assert "::/0" in config.peer.allowed_ips

    def test_tunnel_ip4_extraction(self):
        config = parse_config(SAMPLE_CONFIG)
        assert config.tunnel_ip4 == "10.66.0.5"

    def test_tunnel_ip6_extraction(self):
        config = parse_config(SAMPLE_CONFIG)
        assert config.tunnel_ip6 == "fd86::5"

    def test_endpoint_host_and_port(self):
        config = parse_config(SAMPLE_CONFIG)
        assert config.endpoint_host == "mumbai.vpn.example"
        assert config.endpoint_port == 51820

    def test_validate_valid_config(self):
        config = parse_config(SAMPLE_CONFIG)
        errors = validate_config(config)
        assert errors == []

    def test_validate_missing_private_key(self):
        bad_config = SAMPLE_CONFIG.replace("PrivateKey = yNYuF+gB0xOQ5j6e7w8x9y0z1A2B3C4D5E6F7G8H9I=", "")
        config = parse_config(bad_config)
        errors = validate_config(config)
        assert "Client PrivateKey is missing" in errors

    def test_validate_missing_full_tunnel(self):
        bad_config = SAMPLE_CONFIG.replace("AllowedIPs = 0.0.0.0/0, ::/0", "AllowedIPs = 10.66.0.0/24")
        config = parse_config(bad_config)
        errors = validate_config(config)
        assert any("0.0.0.0/0" in e for e in errors)

    def test_valid_wg_key(self):
        # 32 bytes base64-encoded
        import base64

        key = base64.b64encode(b"a" * 32).decode()
        assert is_valid_wg_key(key) is True

    def test_invalid_wg_key(self):
        assert is_valid_wg_key("not-a-valid-key") is False
        assert is_valid_wg_key("") is False

    def test_mask_private_key(self):
        masked = mask_private_key(SAMPLE_CONFIG)
        assert "PrivateKey = [REDACTED]" in masked
        assert "PrivateKey = yNYuF" not in masked

    def test_raw_preserved(self):
        config = parse_config(SAMPLE_CONFIG)
        assert config.raw == SAMPLE_CONFIG